"use client";
import Link from "next/link";
import { CareerEmptyIllustration } from "@/components/career-visuals";
import { useCallback, useEffect, useMemo, useState } from "react";
import { Activity, ArrowDownWideNarrow, ArrowRight, BarChart3, Bookmark, BriefcaseBusiness, CalendarClock, Check, CheckCircle2, CircleHelp, Clock3, Command, Download, FileText, Gauge, Lightbulb, MapPin, MessageCircle, Plus, Search, Send, Sparkles, Target, TrendingUp, UserRound, X } from "lucide-react";
import { activity, applications, jobs, profile } from "@/lib/demo-data";
import { useCredits } from "@/components/credit-provider";
import { CREDIT_COSTS, CREDIT_LABELS, type CreditAction } from "@/lib/credits";
import { filterJobsByNaturalLanguage, parseNaturalLanguageJobSearch } from "@/lib/search-parser";
import VerificationCenter from "@/components/verification-center";
